function walksToDesk(rows: number, cols: number): number {
  if (rows <= 0 || cols <= 0) return 0;
  const row = new Array(cols).fill(1);
  for (let r = 1; r < rows; r++) for (let c = 1; c < cols; c++) row[c] += row[c - 1];
  return row[cols - 1];
}
